from itertools import permutations

people = ['Logan', 'Reese', 'Riley', 'Taylor']
colors = ['blue', 'green', 'orange', 'white']
pets = ['bird', 'cat', 'dog', 'rabbit']
drinks = ['cocoa', 'coffee', 'tea', 'water']

def is_valid(assignment):
    """Check if assignment satisfies all constraints"""

    def find_person(name):
        for i in range(4):
            if assignment[i]['person'] == name:
                return i
        return -1

    def find_attribute(key, value):
        for i in range(4):
            if assignment[i][key] == value:
                return i
        return -1

    # Constraint 1: Cocoa drinker immediately left of Reese
    reese_house = find_person('Reese')
    cocoa_house = find_attribute('drink', 'cocoa')
    if cocoa_house != reese_house - 1:
        return False

    # Constraint 2: Blue house person drinks cocoa
    blue_house = find_attribute('color', 'blue')
    if assignment[blue_house]['drink'] != 'cocoa':
        return False

    # Constraint 3: Bird owner lives next to Taylor
    taylor_house = find_person('Taylor')
    bird_house = find_attribute('pet', 'bird')
    if abs(taylor_house - bird_house) != 1:
        return False

    # Constraint 4: Cat owner is Riley
    riley_house = find_person('Riley')
    cat_house = find_attribute('pet', 'cat')
    if riley_house != cat_house:
        return False

    # Constraint 5: Logan is bird owner
    logan_house = find_person('Logan')
    if assignment[logan_house]['pet'] != 'bird':
        return False

    # Constraint 6: Green house person owns dog
    green_house = find_attribute('color', 'green')
    dog_house = find_attribute('pet', 'dog')
    if green_house != dog_house:
        return False

    # Constraint 7: Blue house person owns cat
    if assignment[blue_house]['pet'] != 'cat':
        return False

    # Constraint 8: Orange house next to Reese
    orange_house = find_attribute('color', 'orange')
    if abs(orange_house - reese_house) != 1:
        return False

    # Constraint 9: Coffee drinker is Logan
    if assignment[logan_house]['drink'] != 'coffee':
        return False

    # Constraint 10: Rabbit owner not water drinker
    rabbit_house = find_attribute('pet', 'rabbit')
    if assignment[rabbit_house]['drink'] == 'water':
        return False

    # Constraint 11: Taylor next to dog owner
    if abs(taylor_house - dog_house) != 1:
        return False

    return True

# Brute force search through all permutations
found_solution = None
for p_perm in permutations(people):
    for c_perm in permutations(colors):
        for pet_perm in permutations(pets):
            for d_perm in permutations(drinks):
                assignment = []
                for i in range(4):
                    assignment.append({
                        'person': p_perm[i],
                        'color': c_perm[i],
                        'pet': pet_perm[i],
                        'drink': d_perm[i]
                    })

                if is_valid(assignment):
                    found_solution = assignment
                    break
            if found_solution:
                break
        if found_solution:
            break
    if found_solution:
        break

# Extract who lives in green house
if found_solution:
    for i in range(4):
        if found_solution[i]['color'] == 'green':
            print(f"ANSWER: {found_solution[i]['person']}")
            break
